CREATE INDEX IF NOT EXISTS idx_pedidos_criado_em ON pedidos(criado_em DESC);

-- O planejador decide usar o índice a partir das estatísticas da
-- tabela. Depois de criar um índice novo, o ANALYZE evita que ele
-- decida com dado velho e escolha Seq Scan por engano.
ANALYZE pedidos;
ANALYZE itens_pedido;
